    ["Working code rule", "Every record ships a runnable program \u2014 a method you cannot run is just a description."],
    ["Origin", "Created in the Signature system; never presented as public record."]
];
function ask(n){
  var out=[],i,it;
  n=Math.min(n,ITEMS.length);
  for(i=0;i<n;i++){
    it=ITEMS[(Math.random()*ITEMS.length)|0];
    out.push("Q"+(i+1)+": "+it[0]+"\nA"+(i+1)+": "+it[1]);
  }
  return out.join("\n\n");
}
function lookup(q){
  q=String(q).toLowerCase();var hits=[],i;
  for(i=0;i<ITEMS.length;i++){
    if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)
      hits.push(ITEMS[i][0]+" \u2014 "+ITEMS[i][1]);
  }
  return hits.length?hits.join("\n"):"no match for "+q;
}
function quizYourself(){
  var score=0,i,it;
  for(i=0;i<ITEMS.length;i++){
    it=ITEMS[i];
    console.log("TERM: "+it[0]);
    console.log("  -> "+it[1]);
    score++;
  }
  console.log("Reviewed "+score+" of "+ITEMS.length+" cards.");
}
