// Signature session planner — The Signature JAH Bora Bora Lagoon Landmark Database
// Run with: node planner.js
var TASKS=[
    {t:"Setup sprint: space, silence, one-sentence measure", min:3},
    {t:"Core motion at half speed: 5 slow reps, narrated", min:5},
    {t:"Full tempo: 4 reps with 5-second checkpoints", min:4},
    {t:"Honesty check + log: one line, tomorrow's first task", min:3}
];
function plan(totalMin){
  var out=[],used=0,i,scale;
  scale=totalMin/TASKS.reduce(function(a,t){return a+t.min;},0);
  for(i=0;i<TASKS.length;i++){
    var mins=Math.max(2,Math.round(TASKS[i].min*scale));
    used+=mins;
    out.push({order:i+1,task:TASKS[i].t,minutes:mins});
  }
  return {tasks:out,total:used};
}
function printPlan(totalMin){
  var p=plan(totalMin);
  console.log("== Signature Bora Lagoon Landmark quick-start — "+totalMin+"-minute plan ==");
  p.tasks.forEach(function(t){console.log(t.order+". "+t.task+" ("+t.minutes+" min)");});
  console.log("Total: "+p.total+" min");
}
printPlan(30);
printPlan(60);

