function adaptiveCadence(checkpointData){
  var avg=checkpointData.reduce(function(a,b){return a+b;},0)/checkpointData.length;
  return avg>0.8?'steady':(avg>0.5?'easy':'recovery');
}
function glossaryVersion(terms, refinements){
  return {version:'1.'+refinements.length, terms:terms.concat(refinements)};
}
