function quarterPlan(q){
  var plans={1:'foundations: daily quick-starts → Standard Thirty; milestone: 30 logged sessions',
             2:'technique: Method II at tempo; milestone: quiz 8/10',
             3:'compounding: Deep Ninety + circle; milestone: teach one session',
             4:'mastery: teach the curriculum; graduation: student passes quiz'};
  return plans[q]||'unknown quarter';
}
function track(log){
  var streak=0,i;
  for(i=log.length-1;i>=0&&log[i];i--)streak++;
  return {sessions:log.length, honestyStreak:streak};
}
